import Foundation

/// Coefficient tables loaded once from the bundled resources `ephemeris_tables.txt` and
/// `delta_t.txt` (port of astro/EphemerisData.kt). The files in Resources/ are byte-for-byte copies
/// of android/core/src/main/resources/com/metavirtuoso/conjunction/core/astro/ (generated by
/// testdata/tools/make_ephemeris_tables.py and make_golden.py); ResourceParityTests checks it.
struct EphemerisData: Sendable {
    /// One VSOP87 series: amplitudes A, phases B, frequencies C (term = A cos(B + C tau)).
    struct Series: Sendable {
        var a: [Double] = []
        var b: [Double] = []
        var c: [Double] = []
    }

    /// VSOP87D series per body: index [variable 0=L,1=B,2=R][power].
    struct Vsop: Sendable { let series: [[Series]] }

    struct MoonTables: Sendable { let lr: [[Int]]; let b: [[Int]] }

    struct DeltaT: Sendable { let firstYear: Int; let seconds: [Double] }

    let vsop: [String: Vsop]
    let moon: MoonTables
    let pluto: [[Double]]
    let deltaT: DeltaT

    /// Loaded on first use (Swift globals and static lets are lazily and atomically initialised).
    static let shared: EphemerisData = {
        do { return try EphemerisData(tables: read("ephemeris_tables"), deltaT: read("delta_t")) }
        catch { fatalError("Bundled ephemeris resources are corrupt: \(error)") }
    }()

    struct FormatError: Error, CustomStringConvertible { let description: String }

    init(tables lines: [String], deltaT deltaLines: [String]) throws {
        var vsopRaw: [String: [[Series]]] = [:]
        var moonLr: [[Int]]?
        var moonB: [[Int]]?
        var plutoRows: [[Double]]?
        var i = 0
        func next() throws -> [String] {
            guard i < lines.count else { throw FormatError(description: "unexpected end of ephemeris_tables.txt") }
            defer { i += 1 }
            return lines[i].trim().split(" ")
        }
        func ints(_ p: [String]) throws -> [Int] {
            try p.map { guard let v = Int($0) else { throw FormatError(description: "bad int \($0)") }; return v }
        }
        func doubles(_ p: [String]) throws -> [Double] {
            try p.map { guard let v = Double($0) else { throw FormatError(description: "bad number \($0)") }; return v }
        }
        while i < lines.count {
            let header = lines[i].trim()
            i += 1
            if header.isEmpty || header.hasPrefix("#") { continue }
            let h = header.split(" ")
            switch h[0] {
            case "VSOP":
                guard h.count == 5, let n = Int(h[4]), let power = Int(h[3]) else { throw FormatError(description: header) }
                var series = Series()
                for _ in 0..<n {
                    let p = try doubles(try next())
                    guard p.count == 3 else { throw FormatError(description: "VSOP row needs 3 numbers") }
                    series.a.append(p[0]); series.b.append(p[1]); series.c.append(p[2])
                }
                let variable: Int
                switch h[2] {
                case "L": variable = 0
                case "B": variable = 1
                case "R": variable = 2
                default: throw FormatError(description: "bad var \(h[2])")
                }
                var body = vsopRaw[h[1]] ?? [[], [], []]
                while body[variable].count <= power { body[variable].append(Series()) }
                body[variable][power] = series
                vsopRaw[h[1]] = body
            case "MOON_LR":
                guard let n = Int(h[1]) else { throw FormatError(description: header) }
                moonLr = try (0..<n).map { _ in try ints(try next()) }
            case "MOON_B":
                guard let n = Int(h[1]) else { throw FormatError(description: header) }
                moonB = try (0..<n).map { _ in try ints(try next()) }
            case "PLUTO":
                guard let n = Int(h[1]) else { throw FormatError(description: header) }
                plutoRows = try (0..<n).map { _ in try doubles(try next()) }
            default:
                throw FormatError(description: "Unknown section in ephemeris_tables.txt: \(header)")
            }
        }
        vsop = vsopRaw.mapValues { Vsop(series: $0) }
        guard let moonLr else { throw FormatError(description: "MOON_LR missing") }
        guard let moonB else { throw FormatError(description: "MOON_B missing") }
        guard let plutoRows else { throw FormatError(description: "PLUTO missing") }
        moon = MoonTables(lr: moonLr, b: moonB)
        pluto = plutoRows

        let rows = deltaLines.map { $0.trim() }.filter { !$0.isEmpty && !$0.hasPrefix("#") }.map { $0.split(" ") }
        guard let first = rows.first, let firstYear = Int(first[0]) else { throw FormatError(description: "delta_t.txt empty") }
        deltaT = DeltaT(firstYear: firstYear, seconds: try rows.map { try doubles([$0[1]])[0] })
    }

    /// Lines of a bundled resource (ASCII).
    static func read(_ name: String) throws -> [String] {
        guard let url = Bundle.module.url(forResource: name, withExtension: "txt", subdirectory: "Resources")
            ?? Bundle.module.url(forResource: name, withExtension: "txt") else {
            throw FormatError(description: "Missing bundled resource \(name).txt")
        }
        let text = try String(contentsOf: url, encoding: .ascii)
        var lines = text.kotlinLines()
        // readLines() drops the empty string after a final newline.
        if lines.last == "" { lines.removeLast() }
        return lines
    }
}
